import{_ as n}from"./chunks/11.DeTVfB-g.js";import{_ as r}from"./chunks/image1.YJCAcCic.js";import{_ as s,a as l}from"./chunks/image.DUp49IjQ.js";import{_ as c,a,b as d,c as h}from"./chunks/image4.FCpLmD95.js";import{_ as g}from"./chunks/image15.tCW31st1.js";import{_ as m}from"./chunks/image.BikqRkQy.js";import{_ as p,a as t,b as u,c as f}from"./chunks/community.D8XXOc5B.js";import{_}from"./chunks/image6.Cdq5CsCC.js";import{_ as b,C as y,o as v,c as w,aj as o,E as k}from"./chunks/framework.Cwzc8Cgk.js";const x="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.DZjZ5DaY.png",P="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image100.Caq-FLKb.png",I="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.CxIjCJph.png",S="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image6.DgvjV-FZ.png",D="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image7.C1-Hq-rM.png",T="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.BbHH_3Rg.png",N=JSON.parse('{"title":"3.11 AI Phone Stand","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.11 AI Phone Stand.md","filePath":"docs/3. Creative Building & Styling/3.11 AI Phone Stand.md"}'),z={name:"docs/3. Creative Building & Styling/3.11 AI Phone Stand.md"};function A(C,e,q,j,E,L){const i=y("pdf");return v(),w("div",null,[e[0]||(e[0]=o('<h1 id="_3-11-ai-phone-stand" tabindex="-1">3.11 AI Phone Stand <a class="header-anchor" href="#_3-11-ai-phone-stand" aria-label="Permalink to &quot;3.11 AI Phone Stand&quot;">​</a></h1><h2 id="_3-11-1-lesson-introduction" tabindex="-1">3.11.1 Lesson Introduction <a class="header-anchor" href="#_3-11-1-lesson-introduction" aria-label="Permalink to &quot;3.11.1 Lesson Introduction&quot;">​</a></h2><p>The AI Phone Stand is a practical and intelligent robotic building block project designed for automated face tracking. The top of the stand incorporates the WonderLens vision module as its visual camera, while the base employs a 270° block servo to support and rotate the phone cradle. The modular mechanical design ensures straightforward assembly and accessible wiring. When the camera captures a face and reads its horizontal position in the frame, the servo drives the cradle to rotate left and right synchronously, automatically aligning its orientation with the detected face. This project provides hands-on exploration of AI face coordinate tracking and closed-loop servo angle control.</p><img loading="lazy" height="1080" width="1080" src="'+n+'" class="common_img" style="width:300px;"><h2 id="_3-11-2-learning-objectives" tabindex="-1">3.11.2 Learning Objectives <a class="header-anchor" href="#_3-11-2-learning-objectives" aria-label="Permalink to &quot;3.11.2 Learning Objectives&quot;">​</a></h2><ol><li>Master face position tracking using the WonderLens vision module. Learn methods for reading horizontal face coordinates and writing face detection routines.</li><li>Program angle mapping control routines for the 270° block servo, adjusting the left-right rotation angles based on detected face coordinate offsets.</li><li>Complete system linkage debugging across face tracking recognition and servo rotation to achieve synchronized tracking between face motion and stand orientation.</li><li>Assemble the complete stand model and debug the tracking program. Develop foundational skills in building AI vision-based robotic tracking projects.</li></ol><h2 id="_3-11-3-assembly-guide" tabindex="-1">3.11.3 Assembly Guide <a class="header-anchor" href="#_3-11-3-assembly-guide" aria-label="Permalink to &quot;3.11.3 Assembly Guide&quot;">​</a></h2>',7)),k(i,{src:"../../../../docs/_static/shared/pdf/chapter_3/11.pdf"}),e[1]||(e[1]=o('<h2 id="_3-11-4-hardware-wiring" tabindex="-1">3.11.4 Hardware Wiring <a class="header-anchor" href="#_3-11-4-hardware-wiring" aria-label="Permalink to &quot;3.11.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to port <strong>P1</strong> of the ESP32 controller.</p><p>Connect the 270° block servo cable to port <strong>S1</strong> of the ESP32 controller, ensuring the <strong>orange</strong> wire is plugged into the <strong>white</strong> pin of S1.</p><p>Wiring diagram:</p><img loading="lazy" height="1220" width="1100" src="'+x+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When using the 270° block servo for the first time, detach the gear and its attached building block components from the servo before uploading the program. Upload the lesson program to the ESP32 controller and wait for the servo to rotate to its initial home position, 135°. Once initialized, reattach the components. This step can be skipped if a servo homing routine has already been executed.</strong></p></div><img loading="lazy" height="1080" width="1080" src="'+P+'" class="common_img" style="width:300px;"><h2 id="_3-11-5-programming" tabindex="-1">3.11.5 Programming <a class="header-anchor" href="#_3-11-5-programming" aria-label="Permalink to &quot;3.11.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1)  Program Schematic&quot;">​</a></h3><img loading="lazy" height="470" width="370" src="'+I+'" class="common_img" style="width:350px;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+r+'" class="common_img" style="width:800px;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="303" width="408" src="'+s+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+l+'" class="common_img"></td><td style="text-align:left;">Compares the left value with a specified value and returns a boolean result for the greater-than condition.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="173" src="'+c+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+a+'" class="common_img"></td><td style="text-align:left;">Creates a custom variable for data storage.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="115" width="312" src="'+d+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+a+'" class="common_img"></td><td style="text-align:left;">Reads the data stored in the specified custom variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="138" width="522" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+a+'" class="common_img"></td><td style="text-align:left;">Assigns a custom value to the specified variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="103" width="929" src="'+g+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="51" width="75" src="'+m+'" class="common_img"></td><td style="text-align:left;">Rotates the specified servo to the target angle within a set duration and selects the delay mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="412" width="760" src="'+p+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="432" src="'+u+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera feed and reads recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="92" width="760" src="'+S+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Determines whether the specified face ID is detected in the camera frame and returns a boolean result.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="204" width="824" src="'+D+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+t+'" class="common_img"></td><td style="text-align:left;">Reads frame data for the specified face ID, including center coordinates, width, and height.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong> and switch its operating mode to face recognition. Define the variable <code>Angle</code> and assign it an initial value of 135. Set 270° block servo <strong>S1</strong> to rotate to <code>Angle</code> over an execution duration of 1,000 ms, then wait for 2 s.</p></li><li><p>Main Loop: The program continuously updates and retrieves recognition data from the WonderLens vision module. When face ID 1 is recognized, the horizontal X-coordinate of the face center is retrieved and stored in the variable <code>Location</code>. The value of <code>Increase</code> is evaluated based on <code>Location</code>. When <code>Location</code> is greater than 160, <code>Increase</code> is set to 1. When <code>Location</code> is less than 80, <code>Increase</code> is set to -1. Otherwise, <code>Increase</code> is set to 0. The program adds <code>Increase</code> to <code>Angle</code>, constrains <code>Angle</code> within 50° to 220°, and drives 270° block servo <strong>S1</strong> to the updated angle over 20 ms. Each loop iteration pauses for 0.03 s, achieving smooth horizontal face tracking.</p></li></ol><img loading="lazy" height="1059" width="695" src="'+T+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-11-6-program-upload" tabindex="-1">3.11.6 Program Upload <a class="header-anchor" href="#_3-11-6-program-upload" aria-label="Permalink to &quot;3.11.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+_+'" class="common_img" style="width:800px;"><h2 id="_3-11-7-expansion-and-challenge" tabindex="-1">3.11.7 Expansion and Challenge <a class="header-anchor" href="#_3-11-7-expansion-and-challenge" aria-label="Permalink to &quot;3.11.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: Tiered Face ID Tracking and RGB Indication</strong></p><ol><li><p>Project Goal: Differentiate between four operational scenarios: authorized face ID, unregistered passerby, blank frame, and designated face ID 2. Produce distinct tracking speeds and lighting effects. When the authorized face ID is detected, the stand follows the face rapidly and smoothly while the RGB LED flashes continuously. When an unregistered passerby is detected, the stand tracks at a lower, gentler speed. When no face is detected or face ID 2 is recognized, the servo returns the stand to its centered home position, and the RGB LED turns off.</p></li><li><p>Implementation Strategy: Call blocks that read face IDs and coordinates, define identity evaluation variables, and construct multi-tier conditional branches. Configure dedicated servo tracking speeds and RGB lighting logic for authorized faces, ordinary passersby, and absent faces. Program servo homing angles into the centering branch.</p></li><li><p>Key Challenges: Ensuring stable coordinate readings without jitter during tracking, and synchronizing lighting updates with speed transitions when switching between different face identities.</p></li></ol><p><strong>Challenge Task 2: Delayed Centering Standby on Face Departure</strong></p><ol><li><p>Project Goal: When a face moves out of camera view, the stand does not return to the center immediately. Instead, it maintains its current angle for 3 s. Once the countdown expires, the servo automatically resets the stand to its centered standby position, and the RGB LED turns off.</p></li><li><p>Implementation Strategy: Introduce a timer variable to start a countdown upon face disappearance. Maintain the existing tracking angle while the countdown remains active. Reset the servo to the center and extinguish the RGB LED once the timer reaches zero.</p></li><li><p>Key Challenges: Ensuring the timer routine executes without blocking the camera from resuming face detection, and keeping the servo homing motion smooth without mechanical impact.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Face Position Tracking</strong></p><ol><li><p>Face-Tracking Gimbal Camera: Retain the core face coordinate tracking logic and mount the camera on a servo-driven pan-tilt mechanism to follow faces dynamically during filming.</p></li><li><p>Face-Sensing Follow Fill Light: Replace the phone cradle with an LED fill light to automatically adjust lighting angles based on face offset positions.</p></li><li><p>Universal Adaptation Strategy: Keep the core face tracking code unchanged and swap out the mechanical mechanism. By implementing new servo angle mapping commands under the logic of adjusting angles based on face coordinates, diverse interactive tracking devices can be developed.</p></li></ol><h2 id="_3-11-8-q-a" tabindex="-1">3.11.8 Q&amp;A <a class="header-anchor" href="#_3-11-8-q-a" aria-label="Permalink to &quot;3.11.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: During servo wiring, the orange signal wire must connect to the white pin of port S1. What problems occur if it is wired incorrectly?</strong></p><p><strong>Answer</strong>: The white pin of port <strong>S1</strong> is dedicated to transmitting control signals, which the servo relies on to adjust the left-right rotation angle of the stand. If the orange signal wire connects to the power or ground pins, the controller cannot transmit angle commands. Two primary failures occur. First, the servo remains completely motionless, preventing the stand from following face motion. Second, the servo vibrates erratically and rotates uncontrollably, which can cause overheating and hardware damage. In addition, all program code designated for face tracking, angle following, and home resetting becomes ineffective, preventing the automatic tracking function from operating.</p><p><strong>Question 2: The vision module recognizes faces and outputs face coordinates normally, but the phone stand servo does not rotate at all. What are the most common causes and troubleshooting steps?</strong></p><p><strong>Answer</strong>:</p><ol><li><p>Wiring Fault: The orange signal wire of the servo is not connected to the white signal pin of port <strong>S1</strong>. Troubleshooting: Disconnect the power, then verify the three-pin sequence of the servo cable against the wiring diagram.</p></li><li><p>Program Fault: The servo angle following and mapping code is placed outside the conditional loop branch that executes when a face is detected. Troubleshooting: Open the program and verify that the coordinate-to-angle conversion and rotation delay blocks reside inside the valid face detection branch.</p></li><li><p>Hardware Damage: The servo itself is defective, or port <strong>S1</strong> of the ESP32 controller is damaged. Troubleshooting: Connect a known functional servo to port <strong>S1</strong> for testing. If it still does not rotate, connect the servo to an alternative servo port on the controller to isolate the issue.</p></li></ol><h2 id="_3-11-9-technical-support-and-product-discussion" tabindex="-1">3.11.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-11-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.11.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+f+'" class="common_img" style="width:800px;"></a>',37))])}const $=b(z,[["render",A]]);export{N as __pageData,$ as default};
